public class Main {
    static class Spot {
        int id; boolean taken = false;
        Spot(int id) { this.id = id; }
        // check and mark happen together under one lock, so only one gate can win
        synchronized boolean tryAssign() {
            if (taken) return false;
            taken = true;
            return true;
        }
    }

    static void claim(String gate, Spot s) {
        boolean ok = s.tryAssign();
        System.out.println("gate " + gate + " claims spot " + s.id + ": " + (ok ? "ok" : "rejected, retry"));
    }

    public static void main(String[] args) {
        Spot s7 = new Spot(7), s8 = new Spot(8);
        // both gates looked and saw spot 7 free (stale view), then act one after another
        claim("A", s7);
        claim("B", s7);   // the re-check inside tryAssign stops the double booking
        claim("B", s8);   // B retries with the next free spot
    }
}

