public class Main {
    enum Status { ACTIVE, PAID, EXITED }

    static class Ticket {
        Status status = Status.ACTIVE;
        // All legal transitions live in these two methods
        void pay() {
            if (status != Status.ACTIVE) throw new IllegalStateException("cannot pay from " + status);
            status = Status.PAID;
        }
        void exit() {
            if (status != Status.PAID) throw new IllegalStateException("cannot exit from " + status);
            status = Status.EXITED;
        }
    }

    interface Action { void run(); }

    static void attempt(String name, Ticket t, Action a) {
        try { a.run(); System.out.println(name + " -> " + t.status); }
        catch (IllegalStateException e) { System.out.println(name + " -> rejected: " + e.getMessage()); }
    }

    public static void main(String[] args) {
        Ticket t = new Ticket();
        System.out.println("start -> " + t.status);
        attempt("exit", t, t::exit);   // not paid yet
        attempt("pay", t, t::pay);
        attempt("pay", t, t::pay);     // double payment
        attempt("exit", t, t::exit);
    }
}

