public class Main {
    static int n = 3;
    static int[] rows = new int[n], cols = new int[n];
    static int diag = 0, anti = 0;
    // X adds +1, O adds -1; a full line sums to +n or -n.
    // Time O(1) per move, space O(n).
    static boolean move(int r, int c, int p) {
        rows[r] += p;
        cols[c] += p;
        if (r == c) diag += p;            // main diagonal
        if (r + c == n - 1) anti += p;    // anti-diagonal
        return Math.abs(rows[r]) == n || Math.abs(cols[c]) == n
            || Math.abs(diag) == n || Math.abs(anti) == n;
    }
    public static void main(String[] args) {
        int[][] moves = {{0,0},{1,0},{1,1},{0,1},{2,2}};
        for (int i = 0; i < moves.length; i++) {
            int p = i % 2 == 0 ? 1 : -1;
            boolean w = move(moves[i][0], moves[i][1], p);
            System.out.println("move " + (i + 1) + ": " + (p == 1 ? "X" : "O")
                + " at (" + moves[i][0] + "," + moves[i][1] + ") -> " + (w ? "WIN" : "no win"));
        }
    }
}

