import java.util.*;

public class Main {
    static int n = 3;
    static int[] rows = new int[n], cols = new int[n];
    static int diag = 0, anti = 0;
    static boolean over = false;
    static Deque<int[]> undo = new ArrayDeque<>(), redo = new ArrayDeque<>();

    // apply(+1 sign) or reverse (-1 sign) the same counter updates; returns win flag
    static boolean apply(int[] m, int sign) {
        int r = m[0], c = m[1], p = m[2] * sign;
        rows[r] += p; cols[c] += p;
        if (r == c) diag += p;
        if (r + c == n - 1) anti += p;
        return Math.abs(rows[r]) == n || Math.abs(cols[c]) == n || Math.abs(diag) == n || Math.abs(anti) == n;
    }
    static void play(int r, int c, int p) {
        int[] m = {r, c, p};
        over = apply(m, 1);
        undo.push(m);
        redo.clear();                      // a new move invalidates redo history
    }
    static void undo() { int[] m = undo.pop(); apply(m, -1); redo.push(m); over = false; }
    static void redo() { int[] m = redo.pop(); over = apply(m, 1); undo.push(m); }
    static void show(String s) { System.out.println(s + ": over=" + over + " undo=" + undo.size() + " redo=" + redo.size()); }

    public static void main(String[] args) {
        int[][] mv = {{0,0},{1,0},{1,1},{0,1},{2,2}};
        for (int i = 0; i < 5; i++) play(mv[i][0], mv[i][1], i % 2 == 0 ? 1 : -1);
        show("after 5 moves");
        undo(); show("after undo");
        redo(); show("after redo");
        undo(); play(2, 0, 1); show("new move after undo");
    }
}

