    unique_ptr<Pricing> inner;
    ChargingAddOn(unique_ptr<Pricing> p) : inner(move(p)) {}
    int fee(int hours, int kwh) const override { return inner->fee(hours, kwh) + kwh * 8; }
};

// Small factory: wraps only for EV spots
unique_ptr<Pricing> pricingFor(SpotType t) {
    unique_ptr<Pricing> base = make_unique<Hourly>();
    if (t == SpotType::EV) return make_unique<ChargingAddOn>(move(base));
    return base;
}

int main() {
    for (SpotType t : {SpotType::CAR, SpotType::EV}) {
        cout << (t == SpotType::CAR ? "CAR" : "EV") << ": 2 hours, 15 kWh -> fee "
             << pricingFor(t)->fee(2, 15) << endl;
    }
